# Les calculs posés restent du texte mathématique natif, lisible et sélectionnable.
B=chr(92)
def posed(values,op,total):
 rows=[('&+' if i and op=='+' else '&-' if i else '&')+str(v//100)+'{,}'+str(v%100).zfill(2) for i,v in enumerate(values)]
 return '$$'+B+'begin{array}{r}'+(B+B).join(rows).replace('&','')+B+B+B+'hline '+str(total//100)+'{,}'+str(total%100).zfill(2)+B+'end{array}$$'
def add_case(title,intro,values,labels):
 total=sum(values);raw=sum(x%100 for x in values);ret=raw//100
 return E(title,intro,[
 R('Écris toutes les sommes en euros avec deux chiffres pour les centimes.','Convertis les centimes en euros et complète les euros entiers par ,00.',' ; '.join(labels),' ; '.join(eur(v) for v in values)+'.'),
 R('Comment faut-il aligner les nombres pour poser l’addition ?','Place les unités de même valeur les unes sous les autres.','Les virgules sont alignées : euros sous euros, dizaines de centimes sous dizaines de centimes, centimes sous centimes.','Aligne les virgules et les colonnes de même valeur.'),
 R('Additionne les centimes. Faut-il reporter un euro ?','Cent centimes s’échangent contre un euro.',' + '.join(str(v%100) for v in values)+' = '+str(raw)+' centimes.',(str(raw)+' centimes : '+str(ret)+' euro à reporter et '+str(raw%100)+' centimes.' if ret else str(raw)+' centimes, sans euro à reporter.')),
 R('Termine l’addition posée et donne le total.','Ajoute les euros et le report éventuel, puis écris deux chiffres pour les centimes.',posed(values,'+',total),eur(total)+'.'),
 R('Vérifie le total en calculant seulement en centimes.','Convertis chaque prix en centimes puis additionne.','$'+'+'.join(map(str,values))+'='+str(total)+'$.',str(total)+' centimes, soit '+eur(total)+'.')],{'famille':'addition','valeurs_c':values,'total_c':total})
